struct RootView: View {
    var body: some View { TabView { TodayView().tabItem { Label("Šodien", systemImage: "sun.max.fill") }; CalendarView().tabItem { Label("Kalendārs", systemImage: "calendar") }; NotesView().tabItem { Label("Piezīmes", systemImage: "note.text") }; HabitsView().tabItem { Label("Paradumi", systemImage: "leaf.fill") }; ProfileView().tabItem { Label("Profils", systemImage: "person.crop.circle") } }.tint(AppColors.primary).background(AppColors.background) }
}

struct TodayView: View {
    @Environment(\.modelContext) private var context; @Query private var tasks: [TaskItem]; @Query private var habits: [Habit]; @Query private var events: [CalendarEvent]; @State private var adding = false; @State private var editingTask: TaskItem?
    private var today: [TaskItem] { tasks.filter { Calendar.current.isDateInToday($0.dueDate) }.sorted { $0.isCompleted == false && $1.isCompleted == true } }; private var done: Int { today.filter(\.isCompleted).count }; private var dailyMessage: String { let messages = ["Mazs solis šodien ir liels solis uz priekšu.", "Tu vari vairāk, nekā šodien šķiet.", "Atceries arī par sevi un savu mieru.", "Šodiena ir skaista vieta, no kuras sākt.", "Tavas mazās lietiņas veido lielu dienu.", "Lēni un mierīgi — tu visu paspēsi.", "Šodien izvēlies vienu lietu, kas iepriecinās tevi."]; return messages[Calendar.current.ordinality(of: .day, in: .year, for: .now)! % messages.count] }
    var body: some View { NavigationStack { ScrollView { VStack(alignment: .leading, spacing: 18) { Text("Sveika, Vika! ♡").font(.largeTitle.bold()); Text(Date.now.latvianLong.capitalized).foregroundStyle(AppColors.secondary); Text(dailyMessage).italic().foregroundStyle(AppColors.primary)
            AppCard { VStack(alignment: .leading, spacing: 10) { HStack { Text("Šodienas progress").font(.headline); Spacer(); Text("\(done)/\(today.count)").foregroundStyle(AppColors.primary) }; ProgressView(value: today.isEmpty ? 0 : Double(done)/Double(today.count)).tint(AppColors.primary) } }
            section("Steidzamie", tasks: today.filter { !$0.isCompleted && $0.priority == .high }); section("Šodien", tasks: today.filter { !$0.isCompleted && $0.priority != .high }); section("Pabeigtie", tasks: today.filter(\.isCompleted))
            if !habits.isEmpty { Text("Šodienas paradumi").font(.title3.bold()); AppCard { ForEach(habits.filter(\.isActive)) { habit in HabitRow(habit: habit) } } }
            if let event = events.filter({ $0.startDate >= .now }).sorted(by: { $0.startDate < $1.startDate }).first { Text("Nākamais notikums").font(.title3.bold()); AppCard { Label(event.title, systemImage: "calendar.badge.clock"); Text(event.startDate.formatted(date: .abbreviated, time: .shortened)).foregroundStyle(AppColors.secondary) } }
        }.padding() }.background(AppColors.background).navigationTitle("Lietiņas").toolbar { Button { adding = true } label: { Image(systemName: "plus.circle.fill").font(.title2) } }.sheet(isPresented: $adding) { TaskEditor(task: nil) }.sheet(item: $editingTask) { task in TaskEditor(task: task) } } }
    @ViewBuilder private func section(_ title: String, tasks: [TaskItem]) -> some View { if !tasks.isEmpty { Text(title).font(.title3.bold()); AppCard { ForEach(tasks) { task in TaskRow(task: task) { editingTask = task } } } } }
}
struct TaskRow: View { @Environment(\.modelContext) private var context; let task: TaskItem; var onEdit: () -> Void = {}; var body: some View { HStack { Button { task.isCompleted.toggle(); task.completedAt = task.isCompleted ? .now : nil; try? context.save(); Task { await AppServices.shared.notifications.refresh(container: context.container) } } label: { Image(systemName: task.isCompleted ? "checkmark.circle.fill" : "circle").font(.title2).foregroundStyle(task.isCompleted ? AppColors.primary : AppColors.accent) }; VStack(alignment: .leading) { Text(task.title).strikethrough(task.isCompleted); Text(task.category).font(.caption).foregroundStyle(AppColors.secondary) }; Spacer(); if task.imageData != nil { Image(systemName: "photo").foregroundStyle(AppColors.accent) }; Image(systemName: task.priority.icon).foregroundStyle(task.priority == .high ? .red : AppColors.accent) }.padding(.vertical, 4).contentShape(Rectangle()).onTapGesture(perform: onEdit).swipeActions(edge: .trailing, allowsFullSwipe: true) { Button(role: .destructive) { context.delete(task); try? context.save() } label: { Label("Dzēst", systemImage: "trash") } }.contextMenu { Button("Rediģēt") { onEdit() }; Button("Dzēst", role: .destructive) { context.delete(task); try? context.save() } } }
}
struct TaskEditor: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; let task: TaskItem?; @State private var title: String; @State private var details: String; @State private var date: Date; @State private var priority: TaskPriority; @State private var category: String; @State private var reminder: Bool; @State private var reminderDate: Date; @State private var photoItem: PhotosPickerItem?; @State private var imageData: Data?
    init(task: TaskItem?) { self.task = task; _title = State(initialValue: task?.title ?? ""); _details = State(initialValue: task?.details ?? ""); _date = State(initialValue: task?.dueDate ?? .now); _priority = State(initialValue: task?.priority ?? .medium); _category = State(initialValue: task?.category ?? "Personīgais"); _reminder = State(initialValue: task?.reminderDate != nil); _reminderDate = State(initialValue: task?.reminderDate ?? Date().addingTimeInterval(3600)); _imageData = State(initialValue: task?.imageData) }
    var body: some View { NavigationStack { Form { Section("Lietiņa") { TextField("Nosaukums", text: $title); TextField("Apraksts", text: $details, axis: .vertical); DatePicker("Datums", selection: $date, displayedComponents: .date); Picker("Prioritāte", selection: $priority) { ForEach(TaskPriority.allCases) { Text($0.rawValue).tag($0) } }; TextField("Kategorija", text: $category); PhotosPicker(selection: $photoItem, matching: .images) { Label(imageData == nil ? "Pievienot attēlu" : "Mainīt attēlu", systemImage: "photo") }; if let imageData, let image = UIImage(data: imageData) { Image(uiImage: image).resizable().scaledToFit().frame(maxHeight: 160).clipShape(RoundedRectangle(cornerRadius: 12)) } }; Section("Atgādinājums") { Toggle("Iestatīt atgādinājumu", isOn: $reminder); if reminder { DatePicker("Laiks", selection: $reminderDate, in: Date()..., displayedComponents: [.date, .hourAndMinute]) } } }.navigationTitle(task == nil ? "Jauna lietiņa" : "Rediģēt lietiņu").onChange(of: photoItem) { _, item in Task { if let data = try? await item?.loadTransferable(type: Data.self) { imageData = data } } }.toolbar { ToolbarItem(placement: .cancellationAction) { Button("Atcelt") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("Saglabāt") { let cleanTitle = title.trimmingCharacters(in: .whitespacesAndNewlines); guard !cleanTitle.isEmpty else { return }; let value = task ?? TaskItem(title: cleanTitle); if task == nil { context.insert(value) }; value.title = cleanTitle; value.details = details; value.dueDate = Calendar.current.startOfDay(for: date); value.priority = priority; value.category = category; value.reminderDate = reminder ? reminderDate : nil; value.imageData = imageData; try? context.save(); dismiss() } } } } }
}

struct CalendarView: View { @Query private var tasks: [TaskItem]; @Query private var events: [CalendarEvent]; @State private var date = Date(); @State private var adding = false; var body: some View { NavigationStack { List { DatePicker("Izvēlies dienu", selection: $date, displayedComponents: .date).datePickerStyle(.graphical); let dayTasks = tasks.filter { Calendar.current.isDate($0.dueDate, inSameDayAs: date) }; let dayEvents = events.filter { Calendar.current.isDate($0.startDate, inSameDayAs: date) }; Section("Lietiņas") { ForEach(dayTasks) { Text($0.title).strikethrough($0.isCompleted) }; if dayTasks.isEmpty { Text("Šajā dienā nav lietiņu.").foregroundStyle(AppColors.secondary) } }; Section("Notikumi") { ForEach(dayEvents) { event in VStack(alignment: .leading) { Text(event.title); Text(event.startDate.formatted(date: .omitted, time: .shortened)).font(.caption).foregroundStyle(AppColors.secondary) } } } }.scrollContentBackground(.hidden).background(AppColors.background).navigationTitle("Kalendārs").toolbar { Button { adding = true } label: { Image(systemName: "plus") } }.sheet(isPresented: $adding) { NavigationStack { EventEditor(date: date) } } } } }
struct EventEditor: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; let date: Date; @State private var title = ""; @State private var start: Date; @State private var end: Date
    init(date: Date) { self.date = date; _start = State(initialValue: date); _end = State(initialValue: date.addingTimeInterval(3600)) }
    var body: some View { Form { TextField("Notikuma nosaukums", text: $title); DatePicker("Sākums", selection: $start); DatePicker("Beigas", selection: $end) }.navigationTitle("Jauns notikums").toolbar { Button("Saglabāt") { if !title.isEmpty { context.insert(CalendarEvent(title: title, startDate: start, endDate: end)); try? context.save(); dismiss() } } } }
}

struct NotesView: View { @Environment(\.modelContext) private var context; @Query(sort: \Note.updatedAt, order: .reverse) private var notes: [Note]; @State private var search = ""; @State private var adding = false; var filtered: [Note] { notes.filter { search.isEmpty || $0.title.localizedCaseInsensitiveContains(search) || $0.content.localizedCaseInsensitiveContains(search) } }; var body: some View { NavigationStack { List { ForEach(filtered) { note in NavigationLink { NoteEditor(note: note) } label: { VStack(alignment: .leading) { HStack { Text(note.title.isEmpty ? "Bez nosaukuma" : note.title).font(.headline); if note.isPinned { Image(systemName: "pin.fill").foregroundStyle(AppColors.primary) } }; Text(note.content).lineLimit(2).foregroundStyle(AppColors.secondary) } }.swipeActions { Button(role: .destructive) { context.delete(note); try? context.save() } label: { Label("Dzēst", systemImage: "trash") } } } }.searchable(text: $search, prompt: "Meklēt piezīmēs").scrollContentBackground(.hidden).background(AppColors.background).navigationTitle("Piezīmes").toolbar { Button { adding = true } label: { Image(systemName: "plus") } }.sheet(isPresented: $adding) { NavigationStack { NoteEditor(note: nil) } } } } }
struct NoteEditor: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; let note: Note?; @State private var title: String; @State private var content: String; @State private var pinned: Bool; @State private var photoItem: PhotosPickerItem?; @State private var imageData: Data?; init(note: Note?) { self.note = note; _title = State(initialValue: note?.title ?? ""); _content = State(initialValue: note?.content ?? ""); _pinned = State(initialValue: note?.isPinned ?? false); _imageData = State(initialValue: note?.imageData) }; var body: some View { Form { TextField("Virsraksts", text: $title); TextEditor(text: $content).frame(minHeight: 240); PhotosPicker(selection: $photoItem, matching: .images) { Label(imageData == nil ? "Pievienot attēlu" : "Mainīt attēlu", systemImage: "photo") }; if let imageData, let image = UIImage(data: imageData) { Image(uiImage: image).resizable().scaledToFit().frame(maxHeight: 180).clipShape(RoundedRectangle(cornerRadius: 12)) }; Toggle("Piespraust", isOn: $pinned) }.navigationTitle("Piezīme").onChange(of: photoItem) { _, item in Task { if let data = try? await item?.loadTransferable(type: Data.self) { imageData = data } } }.toolbar { Button("Saglabāt") { let n = note ?? Note(); if note == nil { context.insert(n) }; n.title = title; n.content = content; n.isPinned = pinned; n.imageData = imageData; n.updatedAt = .now; try? context.save(); dismiss() } } } }

struct HabitsView: View { @Query private var habits: [Habit]; @Query private var entries: [HabitEntry]; @State private var adding = false; var body: some View { NavigationStack { ZStack { AppColors.background.ignoresSafeArea(); ScrollView { VStack(alignment: .leading, spacing: 16) { Text("Tavi paradumi").font(.largeTitle.bold()); Text("Mazi ieradumi veido lielas pārmaiņas.").foregroundStyle(AppColors.secondary); ForEach(habits.filter(\.isActive)) { habit in HabitRow(habit: habit, entries: entries.filter { $0.habitID == habit.id }) } }.padding(.horizontal, 16).padding(.vertical, 8) } }.navigationTitle("Paradumi").toolbar { Button { adding = true } label: { Image(systemName: "plus.circle.fill").font(.title2) } }.sheet(isPresented: $adding) { HabitEditor() } } } }
struct HabitRow: View {
    @Environment(\.modelContext) private var context
    let habit: Habit
    var entries: [HabitEntry] = []

    private var complete: Bool { entries.contains { Calendar.current.isDateInToday($0.date) && $0.isCompleted } }
    private var goalProgress: Double { min(1, Double(entries.filter(\.isCompleted).count) / Double(max(1, habit.targetDays))) }

    var body: some View {
        AppCard {
            VStack(alignment: .leading, spacing: 12) {
                HStack {
                    VStack(alignment: .leading, spacing: 4) {
                        HStack {
                            Text(habit.title).font(.headline)
                            if habit.isGoal {
                                Text("MĒRĶIS").font(.caption2.bold()).padding(.horizontal, 7).padding(.vertical, 3).background(AppColors.pink).clipShape(Capsule())
                            }
                        }
                        Text("\(habit.category) • \(habit.frequency.rawValue)").font(.caption).foregroundStyle(AppColors.secondary)
                    }
                    Spacer()
                    Button {
                        if complete {
                            if let entry = entries.first(where: { Calendar.current.isDateInToday($0.date) }) { context.delete(entry) }
                        } else {
                            context.insert(HabitEntry(habitID: habit.id))
                        }
                        try? context.save()
                    } label: {
                        Image(systemName: complete ? "checkmark.circle.fill" : "circle").font(.title).foregroundStyle(AppColors.primary)
                    }
                }
                if habit.isGoal {
                    HStack {
                        ProgressView(value: goalProgress).tint(AppColors.primary)
                        Text("\(entries.filter(\.isCompleted).count)/\(habit.targetDays)").font(.caption).foregroundStyle(AppColors.secondary)
                    }
                } else {
                    Text("Šodien: \(complete ? "paveikts" : "vēl jāizdara") • Sērija: \(streak)").font(.caption).foregroundStyle(AppColors.secondary)
                }
            }
        }
    }

    private var streak: Int {
        var count = 0
        var day = Date()
        while entries.contains(where: { Calendar.current.isDate($0.date, inSameDayAs: day) && $0.isCompleted }) {
            count += 1
            day = Calendar.current.date(byAdding: .day, value: -1, to: day)!
        }
        return count
    }
}
struct HabitEditor: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; @State private var title = ""; @State private var frequency = HabitFrequency.daily; @State private var category = "Labsajūta"; @State private var isGoal = false; @State private var targetDays = 30; let categories = ["Labsajūta", "Mācības", "Darbs", "Kustība", "Mājoklis", "Personīgais"]; var body: some View { NavigationStack { Form { Section("Paradums") { TextField("Paraduma nosaukums", text: $title); Picker("Kategorija", selection: $category) { ForEach(categories, id: \.self) { Text($0) } }; Picker("Biežums", selection: $frequency) { ForEach(HabitFrequency.allCases) { Text($0.rawValue).tag($0) } } }; Section("Progress") { Toggle("Šis ir mērķis", isOn: $isGoal); if isGoal { Stepper("Mērķis: \(targetDays) dienas", value: $targetDays, in: 1...365) } else { Text("Bez mērķa — vienkārši ikdienas lietiņa.").font(.caption).foregroundStyle(AppColors.secondary) } } }.navigationTitle("Jauns paradums").toolbar { ToolbarItem(placement: .cancellationAction) { Button("Atcelt") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("Saglabāt") { let cleanTitle = title.trimmingCharacters(in: .whitespacesAndNewlines); guard !cleanTitle.isEmpty else { return }; context.insert(Habit(title: cleanTitle, frequency: frequency, category: category, isGoal: isGoal, targetDays: targetDays)); try? context.save(); dismiss() } } } } } }

struct ProfileView: View { @Query private var goals: [Goal]; @State private var addingGoal = false; @State private var showingSettings = false; var body: some View { NavigationStack { List { Section { HStack { Image(systemName: "heart.circle.fill").font(.system(size: 52)).foregroundStyle(AppColors.primary); VStack(alignment: .leading) { Text("Vika").font(.title.bold()); Text("Tavs personīgais plānotājs").foregroundStyle(AppColors.secondary) } } }.listRowBackground(Color.clear); Section("Personīgie mērķi") { ForEach(goals) { goal in VStack(alignment: .leading) { HStack { Text(goal.title); Spacer(); Text("\(Int(goal.progress))%") }; ProgressView(value: goal.progress / 100).tint(AppColors.primary) } }; Button { addingGoal = true } label: { Label("Pievienot mērķi", systemImage: "plus") } }; Section("Iestatījumi") { Button { showingSettings = true } label: { Label("Datu drošība", systemImage: "lock.shield") }; Button { AppServices.shared.notifications.openSettings() } label: { Label("Paziņojumu iestatījumi", systemImage: "bell") } }; Section("Par Lietiņām") { NavigationLink("Statistika") { StatisticsView() }; Text("Lietiņas 1.0 • Izveidots ar rūpēm").font(.caption).foregroundStyle(AppColors.secondary) } }.scrollContentBackground(.hidden).background(AppColors.background).navigationTitle("Profils").sheet(isPresented: $addingGoal) { NavigationStack { GoalEditor() } }.sheet(isPresented: $showingSettings) { BackupSettingsView() } } } }
struct GoalEditor: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; @State private var title = ""; @State private var description = ""; var body: some View { Form { TextField("Mērķis", text: $title); TextField("Apraksts", text: $description) }.navigationTitle("Jauns mērķis").toolbar { Button("Saglabāt") { if !title.isEmpty { context.insert(Goal(title: title, description: description)); try? context.save(); dismiss() } } } } }
struct StatisticsView: View { @Query private var tasks: [TaskItem]; @Query private var entries: [HabitEntry]; var body: some View { List { Section("Kopsavilkums") { LabeledContent("Pabeigtas lietiņas", value: "\(tasks.filter(\.isCompleted).count)"); LabeledContent("Izpildes līmenis", value: tasks.isEmpty ? "0%" : "\(Int(Double(tasks.filter(\.isCompleted).count) / Double(tasks.count) * 100))%"); LabeledContent("Paradumu ieraksti", value: "\(entries.filter(\.isCompleted).count)") } }.navigationTitle("Statistika") } }

struct BackupSettingsView: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; @State private var automatic = UserDefaults.standard.object(forKey: "autoBackup") as? Bool ?? true; @State private var picker = false; @State private var restorePicker = false; @State private var message = ""; var body: some View { NavigationStack { Form { Section("Datu drošība") { Toggle("Automātiskās rezerves kopijas", isOn: $automatic).onChange(of: automatic) { _, value in UserDefaults.standard.set(value, forKey: "autoBackup") }; Text("Rezerves kopijas tiek veidotas reizi dienā, kad Lietiņas tiek atvērtas. Tās glabājas ārpus lietotnes datiem.").font(.caption).foregroundStyle(AppColors.secondary) }; Section { Button("Izvēlēties backup mapi") { picker = true }; Button("Izveidot rezerves kopiju tagad") { do { let url = try AppServices.shared.backups.create(container: context.container); message = "Saglabāts: \(url.lastPathComponent)" } catch { message = "Neizdevās izveidot kopiju." } }; Button("Atjaunot no rezerves kopijas") { restorePicker = true }; if let date = UserDefaults.standard.object(forKey: "lastBackup") as? Date { LabeledContent("Pēdējā kopija", value: date.formatted(date: .abbreviated, time: .shortened)) }; if !message.isEmpty { Text(message).font(.caption) } } }.navigationTitle("Datu drošība").toolbar { Button("Gatavs") { dismiss() } }.sheet(isPresented: $picker) { FolderPicker() }.sheet(isPresented: $restorePicker) { RestorePicker(container: context.container) } } } }
struct FolderPicker: UIViewControllerRepresentable { @Environment(\.dismiss) private var dismiss; func makeUIViewController(context: Context) -> UIDocumentPickerViewController { let p = UIDocumentPickerViewController(forOpeningContentTypes: [.folder], asCopy: false); p.allowsMultipleSelection = false; p.delegate = context.coordinator; return p }; func updateUIViewController(_ controller: UIDocumentPickerViewController, context: Context) {}; func makeCoordinator() -> Coordinator { Coordinator(self) }; final class Coordinator: NSObject, UIDocumentPickerDelegate { let parent: FolderPicker; init(_ parent: FolderPicker) { self.parent = parent }; func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls: [URL]) { guard let url = urls.first else { return }; if url.startAccessingSecurityScopedResource() { UserDefaults.standard.set(url, forKey: "backupFolder"); url.stopAccessingSecurityScopedResource() }; parent.dismiss() } } }
struct RestorePicker: UIViewControllerRepresentable { let container: ModelContainer; @Environment(\.dismiss) private var dismiss; func makeUIViewController(context: Context) -> UIDocumentPickerViewController { let p = UIDocumentPickerViewController(forOpeningContentTypes: [.json], asCopy: true); p.delegate = context.coordinator; return p }; func updateUIViewController(_ controller: UIDocumentPickerViewController, context: Context) {}; func makeCoordinator() -> Coordinator { Coordinator(self) }; final class Coordinator: NSObject, UIDocumentPickerDelegate { let parent: RestorePicker; init(_ parent: RestorePicker) { self.parent = parent }; func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls: [URL]) { guard let url = urls.first else { return }; do { try AppServices.shared.backups.restore(from: url, container: parent.container) } catch { print("Restore failed: \(error)") }; parent.dismiss() } } }
